import { boolean, customType, index, integer, jsonb, pgTable, text, timestamp, uniqueIndex, type AnyPgColumn } from "drizzle-orm/pg-core";
import { exactNumeric, Decimal } from "../decimal";
import { createId } from "../ids";
import { assets, assetMaintenances } from "./assets";
import { materialMovements } from "./assets-stock";
import { departments } from "./administration";
import type { JsonValue } from "../json";

// The installed DATE columns are calendar days, exposed as UTC midnight just
// like the previous persistence boundary. No DDL is generated by this module.
const day = customType<{ data: Date; driverData: string }>({ dataType: () => "date", fromDriver: value => new Date(`${value.slice(0, 10)}T00:00:00.000Z`), toDriver: value => value.toISOString().slice(0, 10) });
const id = () => text("id").primaryKey().$defaultFn(createId);
const createdAt = () => timestamp("createdAt", { precision: 3 }).notNull().defaultNow();
const updatedAt = () => timestamp("updatedAt", { precision: 3 }).notNull().$defaultFn(() => new Date()).$onUpdateFn(() => new Date());
const quantity = (name: string) => exactNumeric(name, { precision: 14, scale: 3 });
const money = (name: string) => exactNumeric(name, { precision: 18, scale: 2 });
const instant = (name: string) => timestamp(name, { precision: 3 });
const json = (name: string) => jsonb(name).$type<JsonValue>();

export const fleetUnits = pgTable("FleetUnit", {
  id: id(), code: text("code").notNull(), name: text("name").notNull(), category: text("category").notNull(), status: text("status").notNull().default("ATIVO"), operationalStatus: text("operationalStatus").notNull().default("ATIVO"), patrimonyStatus: text("patrimonyStatus"), plate: text("plate"), renavam: text("renavam"), brand: text("brand"), model: text("model"), year: integer("year"), notes: text("notes"), departmentId: text("departmentId"), assetId: text("assetId").references(() => assets.id, { onDelete: "restrict", onUpdate: "cascade" }), responsibleId: text("responsibleId"), parentId: text("parentId").references((): AnyPgColumn => fleetUnits.id, { onDelete: "restrict", onUpdate: "cascade" }), createdById: text("createdById").notNull(), createdAt: createdAt(), updatedAt: updatedAt(),
}, t => [uniqueIndex("FleetUnit_code_key").on(t.code), uniqueIndex("FleetUnit_plate_key").on(t.plate), uniqueIndex("FleetUnit_assetId_key").on(t.assetId), index("FleetUnit_departmentId_category_status_code_idx").on(t.departmentId, t.category, t.status, t.code)]);
